/*
# Add brand column to error_codes and load brand-specific codes

1. What this does
- Adds an optional `brand` text column to the existing `error_codes` table.
  Empty string means "universal / any brand" (existing rows keep working).
- Loads a large reference set of brand-specific error codes supplied by the
  customer: washing machines (Samsung, Bosch/Siemens, Indesit/Hotpoint-Ariston,
  Electrolux/AEG/Zanussi, Beko), dishwashers (Bosch/Siemens/Neff,
  Electrolux/AEG) and TV indicator diagnostics (Sony, LG, Philips).

2. Tables modified
- `error_codes`:
  - New column `brand text NOT NULL DEFAULT ''`.
  - New rows INSERTed; existing rows are NOT touched.

3. Idempotency
- Column added conditionally via DO block.
- INSERT guarded by NOT EXISTS on (category, brand, code, description).

4. Security
- No changes. RLS and existing policies remain as-is.
*/

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'error_codes' AND column_name = 'brand'
  ) THEN
    ALTER TABLE error_codes ADD COLUMN brand text NOT NULL DEFAULT '';
  END IF;
END $$;

INSERT INTO error_codes (category, brand, code, description, cause, solution)
SELECT v.category, v.brand, v.code, v.description, v.cause, v.solution
